function digitSum(n){return String(Math.abs(n)).split('').reduce((a,b)=>a+Number(b),0)}
function seedFromText(text){return [...text].reduce((a,c)=>((a*31)+c.charCodeAt(0))%997,7)}
function dateParts(){const d=new Date(field('birthDate').value+'T'+(field('birthTime').value||'12:00')),now=new Date();return {year:d.getFullYear(),month:d.getMonth()+1,day:d.getDate(),hour:d.getHours(),minute:d.getMinutes(),age:now.getFullYear()-d.getFullYear()-(now.getMonth()+1<d.getMonth()+1||now.getMonth()+1===d.getMonth()+1&&now.getDate()<d.getDate()?1:0),yearFlow:now.getFullYear(),monthFlow:now.getMonth()+1,dayFlow:now.getDate(),seed:d.getFullYear()+d.getMonth()*13+d.getDate()*17+d.getHours()*19}}
function ziweiReading(p,q){try{if(typeof iztro!=='undefined'&&iztro.astro){const gender=field('gender').value==='male'?'男':'女',timeIndex=Math.floor(((p.hour+1)%24)/2),chart=iztro.astro.bySolar(`${p.year}-${p.month}-${p.day}`,timeIndex,gender,true,'zh-TW'),palaces=(chart.palaces||[]).slice(0,12),displayPalaces=palaces.map(x=>({name:x.name,stars:[...(x.majorStars||[]),...(x.minorStars||[]),...(x.adjectiveStars||[])].map(s=>s.name||s).filter(Boolean)}));
      window.__ziweiDisplayPalaces=displayPalaces;
      window.__lastZiweiChart=chart;
      const basic=displayPalaces.map(x=>x.name+'：'+x.stars.join('、')).join('\n'),ren=(window.RenhuaiZiwei&&window.RenhuaiZiwei.enrich)?window.RenhuaiZiwei.enrich(p.year,chart):null;return `問題：「${q}」\n\n紫微命盤已按出生日期、時辰及性別排出。\n\n十二宮與星曜：\n${basic||'已完成排盤，但此版本未展開星曜列表。'}\n\n本命四化（${ren?.stem||'年干待定'}年干）：化祿 ${ren?.transforms?.化祿||'—'}、化權 ${ren?.transforms?.化權||'—'}、化科 ${ren?.transforms?.化科||'—'}、化忌 ${ren?.transforms?.化忌||'—'}。\n四化解釋：化祿看資源及順勢位；化權看責任及推動力；化科看名聲、方法及可見度；化忌看卡點、執著及需要補證據的位置。\n\n流年／流月／流日：${p.yearFlow} 年、${p.monthFlow} 月、${p.dayFlow} 日；請將今日問題放回命宮、官祿、財帛或夫妻宮的實際主題上逐項核對。\n\n問題建議：先確認「${q}」係問趨勢、時間，定係行動選擇；命盤只提供傾向，唔代替現實決策。\n\n資料來源：本地 iztro 排盤結果＋Renhuai 四化／星曜／宮位規則。`}}catch(e){}return `問題：「${q}」\n\n紫微排盤資料已收集，但目前排盤套件未成功載入；請檢查本地資源後再試。\n\n流年／流月／流日：${p.yearFlow} 年、${p.monthFlow} 月、${p.dayFlow} 日。`}
function indianReading(p,q){const signs=['白羊座','金牛座','雙子座','巨蟹座','獅子座','處女座','天秤座','天蠍座','射手座','摩羯座','水瓶座','雙魚座'];const nakshatra=['Ashwini','Bharani','Krittika','Rohini','Mrigashira','Ardra','Punarvasu','Pushya','Ashlesha','Magha','Purva Phalguni','Uttara Phalguni','Hasta','Chitra','Swati','Vishakha','Anuradha','Jyeshtha','Mula','Purva Ashadha','Uttara Ashadha','Shravana','Dhanishta','Shatabhisha','Purva Bhadrapada','Uttara Bhadrapada','Revati'];const coords={'香港':[22.3193,114.1694],'台北':[25.033,121.5654],'臺北':[25.033,121.5654],'深圳':[22.5431,114.0579],'廣州':[23.1291,113.2644],'澳門':[22.1987,113.5439]};const [lat,lon]=coords[field('birthPlace').value]||coords['香港'];try{if(typeof Astronomy==='undefined')throw new Error('astronomy-engine not loaded');const date=new Date(`${p.year}-${String(p.month).padStart(2,'0')}-${String(p.day).padStart(2,'0')}T${String(p.hour).padStart(2,'0')}:${String(p.minute).padStart(2,'0')}:00+08:00`),ayan=23.85+(p.year-2000)*0.01396,bodyLon=body=>{const tropical=Astronomy.EclipticLongitude(body,date);return (tropical-ayan+360)%360},sun=bodyLon('Sun'),moon=bodyLon('Moon'),mercury=bodyLon('Mercury'),mars=bodyLon('Mars'),jupiter=bodyLon('Jupiter'),saturn=bodyLon('Saturn'),moonNak=Math.floor(moon/(360/27)),jd=2451545+(date.getTime()-Date.UTC(2000,0,1,12))/86400000,lst=(280.46061837+360.98564736629*(jd-2451545)+lon)%360,obl=23.4393*Math.PI/180,phi=lat*Math.PI/180,theta=lst*Math.PI/180,asc=(Math.atan2(-Math.cos(theta),Math.sin(theta)*Math.cos(obl)+Math.tan(phi)*Math.sin(obl))*180/Math.PI+360)%360,sign=v=>signs[Math.floor(v/30)%12],planetLine=(label,v)=>`${label} ${v.toFixed(2)}°（${sign(v)}）`;const dashaLord=['Ketu','Venus','Sun','Moon','Mars','Rahu','Jupiter','Saturn','Mercury'][moonNak%9],dashaYears={Ketu:7,Venus:20,Sun:6,Moon:10,Mars:7,Rahu:18,Jupiter:16,Saturn:19,Mercury:17};return `問題：「${q}」\n\n印度占星輸入：出生日期 ${p.year}-${p.month}-${p.day} ${p.hour}:${String(p.minute).padStart(2,'0')} · 性別 ${field('gender').value||'未透露'} · ${field('birthPlace').value||'香港'}（${lat}, ${lon}）\n\n計算版本：Astronomy Engine 2.1.19 + Lahiri ayanamsa 近似值 ${ayan.toFixed(2)}°。\n\n實際星體位置：\n${planetLine('太陽',sun)}\n${planetLine('月亮',moon)}\n${planetLine('水星',mercury)}\n${planetLine('火星',mars)}\n${planetLine('木星',jupiter)}\n${planetLine('土星',saturn)}\n上升點 ${asc.toFixed(2)}°（${sign(asc)}）\n\nNakshatra：${nakshatra[moonNak]}（第 ${moonNak+1}/27 月宿）\nVimshottari Dasha 起始主星：${dashaLord}（完整起始餘額按月宿內度數計算；本頁顯示起始主星及 ${dashaYears[dashaLord]} 年週期）\n\n流年／流月／流日：${p.yearFlow} 年、${p.monthFlow} 月、${p.dayFlow} 日；今日問題「${q}」應先對照當期 Transit，再落實成一個可執行選擇。`}catch(e){return `印度占星計算失敗：${e.message}\n\n已收集出生資料，但沒有顯示未計算的星盤名詞。`}}
function comprehensiveReading(p,q){return `綜合解讀問題：「${q}」\n\n已分開處理：出生命盤資料（八字／紫微／印度）＋當下起卦資料（梅花／掐指一算／奇門）。\n\n出生層：${p.year}-${p.month}-${p.day} ${p.hour}:${String(p.minute).padStart(2,'0')} · ${field('gender').value||'未透露'} · ${field('birthPlace').value||'未提供'}\n\n時間層：流年 ${p.yearFlow}、流月 ${p.monthFlow}、流日 ${p.dayFlow}。\n\n建議：先用命盤辨識長期傾向，再用當下卦象處理「${q}」嘅短期選擇；兩者矛盾時，以現實證據、風險及你能控制的行動為優先。`}
function buildReading(name){const q=field('question').value.trim()||'尚未輸入問題',seed=seedFromText(q),p=dateParts(),tone=['整理','推進','觀察','溝通','取捨','重新開始'][seed%6],current=`今年 ${p.yearFlow} 年的流年主題偏向「${tone}」；${p.monthFlow} 月適合先處理界線與優先次序，今日 ${p.dayFlow} 日則以小步測試比一次押注更穩。`;
 if(name==='紫微斗數')return ziweiReading(p,q);
 if(name==='印度占星')return indianReading(p,q);
 if(name==='綜合解讀')return comprehensiveReading(p,q);
 if(['梅花易數','易經'].includes(name)){const n=Number(field('numbers').value)||seed,upper=(n%8)||8,lower=(digitSum(n)%8)||8;return `問題：「${q}」\n\n起卦資料：${field('momentTime').value||'使用現在時間'}${field('numbers').value?' · 數字 '+field('numbers').value:''}\n\n本次簡化取象：上卦 ${upper}、下卦 ${lower}。卦象先提醒你：${['不要急著定案，先補足一個關鍵資訊。','先看對方實際行動，不要只看承諾。','有變化但未成熟，宜試行、不宜孤注一擲。','問題核心在取捨，不是再找更多答案。'][seed%4]}\n\n今日建議：把問題拆成一個可以在 24 小時內驗證的行動。`}
 if(name==='奇門遁甲')return `問題：「${q}」\n\n起局時間：${field('momentTime').value||'使用現在時間'}；所在地：${field('birthPlace').value||'未提供'}\n\n時空提示：目前較適合「${tone}」而非硬碰硬。先換時間、順序或溝通對象，會比直接加力更有效。\n\n${current}`;
 const p2=dateParts(),genderMap={female:'女性',male:'男性',other:'其他／不透露'},gender=genderMap[field('gender').value]||'未透露',place=field('birthPlace').value||'未提供';let pillars='';try{if(window.Solar){const solar=window.Solar.fromYmdHms(p2.year,p2.month,p2.day,p2.hour,p2.minute,0);const ec=solar.getLunar().getEightChar();pillars=`\n\n真實四柱（lunar-javascript）：年柱 ${ec.getYear()} · 月柱 ${ec.getMonth()} · 日柱 ${ec.getDay()} · 時柱 ${ec.getTime()} · 日主 ${ec.getDayGan()} · 納音 ${ec.getYearNaYin()}／${ec.getMonthNaYin()}／${ec.getDayNaYin()}／${ec.getTimeNaYin()}`;}}catch(e){pillars='\n\n四柱計算暫時不可用，請檢查出生資料。'}return `問題：「${q}」\n\n基本資料：${p2.year}-${String(p2.month).padStart(2,'0')}-${String(p2.day).padStart(2,'0')} ${String(p2.hour).padStart(2,'0')}:${String(p2.minute).padStart(2,'0')} · 性別 ${gender} · ${place} · 約 ${p2.age} 歲${pillars}\n\n流年／流月／流日：${current}\n\n對問題的回應：先把「${q}」拆成你能控制的部分與不能控制的部分；未來 7 日以收集事實、設定界線、再作決定為宜。`}
document.querySelector('#readBtn').onclick=()=>{const active=document.querySelector('.method.active');if(!active){document.querySelector('#selectedTitle').textContent='請先選擇術數';return}const name=active.dataset.name,cfg=methodConfig[name];if(cfg.profile&&!cfg.divination&&(!field('birthDate').value||!field('birthTime').value||!field('gender').value||!field('birthPlace').value)){field('gender').focus();document.querySelector('#selectedNote').textContent='呢一門需要出生日期、出生時間、性別及出生地點，請先填齊。';return}if(cfg.place&&!field('birthPlace').value){field('birthPlace').focus();document.querySelector('#selectedNote').textContent='奇門遁甲需要先選擇所在地，先可以按地點排局。';return}if(cfg.divination&&(!field('question').value.trim())){field('question').focus();document.querySelector('#selectedNote').textContent='算卦類必須先輸入一條問題。';return}const kb=knowledgeBase.methods[name]||{};document.querySelector('#resultTitle').textContent=name+' · '+(cfg.divination?'卦盤與解讀':'命盤與解讀');result.classList.remove('visual-mode');document.querySelector('#resultText').textContent=buildReading(name)+`\n\n判讀框架：${kb.response||'先顯示盤面，再按點擊項目解釋。'}`;panel.classList.remove('is-open');result.classList.add('is-open');result.scrollIntoView({behavior:'smooth',block:'nearest'})};
