// Keep the result focused on the user's question; calculation provenance is not part of the reading.
document.querySelector('#readBtn').addEventListener('click',()=>setTimeout(()=>{
  const resultText=document.querySelector('#resultText');
  if(resultText) resultText.textContent=resultText.textContent
    .replace(/\n\n資料來源：[^\n]+/g,'')
    .replace(/\n\n?資料層：[^\n]+/g,'')
    .replace(/\n\n?來源審計：[^\n]+/g,'')
    .replace(/\n\n?來源：[^\n]+/g,'');
},80),false);

// Keep every result tied to an explicit question and expose the location only for Qi Men.
document.querySelectorAll('.method').forEach(btn=>btn.addEventListener('click',()=>{
  const name=btn.dataset.name,cfg=methodConfig[name];
  document.querySelectorAll('.interactive-result').forEach(host=>{host.hidden=true;host.innerHTML='';host.classList.remove('method-rich-active');});
  const questionLabel=document.querySelector('.question-label');
  if(questionLabel) questionLabel.style.display='block';
  const genderLabel=document.querySelector('#gender')?.closest('label');
  if(genderLabel) genderLabel.style.display=cfg.place&&!cfg.profile?'none':'';
},false));
document.addEventListener('click',event=>{
  if(!event.target.closest('#readBtn')) return;
  const active=document.querySelector('.method.active'),cfg=active&&methodConfig[active.dataset.name];
  if(!cfg||document.querySelector('#question')?.value.trim()) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  const question=document.querySelector('#question');
  question?.focus();
  const note=document.querySelector('#selectedNote');
  if(note) note.textContent='先寫低你今次真正想問嘅一件事，結果先會按問題解讀。';
},true);
